// Compiled artifact for the LoyaltyToken contract used by
// /api/fuse/loyalty/create. Source Solidity (^0.8.20):
//
//   contract LoyaltyToken {
//     string  name; string  symbol; uint8 decimals = 18;
//     uint256 totalSupply;
//     address owner;                              // single admin
//     mapping(address=>bool)  minters;            // mint() ACL
//     mapping(address=>uint256) balanceOf;
//     mapping(address=>mapping(address=>uint256)) allowance;
//
//     constructor(string name, string symbol, uint256 initialSupply,
//                 address owner, address initialMinter)
//       sets owner = _owner, minters[_initialMinter] = true,
//       mints initialSupply to _owner.
//
//     function setMinter(address, bool)  onlyOwner    // revoke server etc.
//     function transferOwnership(address) onlyOwner
//     function mint(address, uint256)    onlyMinter
//     function burn(uint256)
//     function transfer / approve / transferFrom (standard ERC-20)
//   }
//
// Custody model: owner = caller (passed via POST body); initialMinter =
// server deployer wallet. The owner can revoke the server's minter role
// on-chain at any time via setMinter(deployer, false) — at which point
// /api/fuse/loyalty/mint stops being able to mint for that token.
//
// Compiled with solc 0.8.24, optimizer enabled (200 runs). The bytecode is
// embedded so the runtime never needs solc — viem.deployContract(bytecode,
// args) produces a deterministic deployment from these constants.
//
// To regenerate: see the LoyaltyToken.sol source in PRs (kept in commit
// history rather than this repo to avoid carrying a Solidity toolchain).

